insert into inteligencia.achado (dossie_id, camada_codigo, camada_nome, severidade, resultado, implicacao, base_legal, metricas, origem) select currval('inteligencia.dossie_id_seq'), c.codigo, c.nome, 'condiciona', '10 de 20 unidades a menos de 30 m de corpo d''água; o perímetro toca a margem.', 'Faixa não edificável de 15 m (REURB-E) ou estudo técnico com melhoria ambiental (REURB-S, art. 64).', c.base_legal, '{"distancia_min_m": 0.0, "unidades_na_faixa": 10, "faixa_m": 30.0}'::jsonb, 'calculado' from inteligencia.camada c where c.codigo = 'hidrografia_app';
